def calendar(marks, c=PK):
    return [R(120, 50, 100, 100, CR), R(120, 50, 100, 22, c), R(138, 40, 6, 20, GS), R(196, 40, 6, 20, GS)] + [R(130 + 22 * (i % 4), 82 + 20 * (i // 4), 14, 12, OR if i in marks else GS) for i in range(12)]


def angry(cx, cy, c=PK):
    return face(cx, cy, 30, c) + [line(cx - 20, cy - 14, cx - 6, cy - 8, 3, IN), line(cx + 20, cy - 14, cx + 6, cy - 8, 3, IN), R(cx - 10, cy + 12, 20, 4, IN)]


